import json

with open('/app/output/solution.json', 'r') as f:
    solution = json.load(f)

print(f"Makespan: {solution['makespan']}")
print(f"Operations scheduled: {len(solution['schedule'])}")

# Check for downtime violations
downtimes = {
    1: (5, 20),
    2: (12, 25)
}

violations = 0
for item in solution['schedule']:
    machine = item['machine']
    start = item['start']
    end = item['end']

    if machine in downtimes:
        down_start, down_end = downtimes[machine]
        if not (end <= down_start or start >= down_end):
            violations += 1
            print(f"VIOLATION: Job {item['job']}, Op {item['op']} on Machine {machine} [{start}, {end})")

if violations == 0:
    print("No downtime violations ✓")

# Check job precedence
print("\nJob precedence check:")
job_ops = {}
for item in solution['schedule']:
    job = item['job']
    op = item['op']
    if job not in job_ops:
        job_ops[job] = {}
    job_ops[job][op] = item

valid = True
for job_id in sorted(job_ops.keys()):
    ops = job_ops[job_id]
    for op_idx in range(len(ops)):
        if op_idx > 0:
            if ops[op_idx - 1]['end'] > ops[op_idx]['start']:
                print(f"VIOLATION: Job {job_id} precedence violated")
                valid = False

if valid:
    print("All job precedences respected ✓")
EOF

